const fs = require('fs');
const path = require('path');
const dir = '.';
const regions = ['north', 'south', 'east', 'west'];
const inspector = {
  north: { count: 10, units: 90, weighted: 167 },
  south: { count: 10, units: 94, weighted: 171 },
  east:  { count: 10, units: 98, weighted: 209 },
  west:  { count: 10, units: 85, weighted: 145 }
};
const out = { regions: {}, grand_units: 0, grand_weighted: 0 };
const checks = [];
let ok = true;
for (const r of regions) {
  const p = path.join(dir, r + '.json');
  const raw = fs.readFileSync(p, 'utf8');
  let data;
  try { data = JSON.parse(raw); } catch (e) { ok = false; checks.push(`${r}: JSON parse FAILED ${e.message}`); continue; }
  if (!Array.isArray(data)) { ok = false; checks.push(`${r}: not an array`); continue; }
  let units = 0, weighted = 0, badFields = [];
  const ids = new Set();
  for (const rec of data) {
    if (!rec || typeof rec !== 'object') { badFields.push('non-object'); continue; }
    if (!Number.isInteger(rec.units) || !Number.isInteger(rec.weight)) { badFields.push(JSON.stringify(rec)); continue; }
    if (ids.has(rec.id)) badFields.push('dup id ' + rec.id);
    ids.add(rec.id);
    units += rec.units;
    weighted += rec.units * rec.weight;
  }
  const sorted = [...ids].sort((a, b) => a - b);
  const contiguous = sorted.length === data.length && sorted.every((v, i) => v === i + 1);
  const bytes = Buffer.byteLength(raw, 'utf8');
  out.regions[r] = { count: data.length, units, weighted };
  out.grand_units += units;
  out.grand_weighted += weighted;
  const exp = inspector[r];
  const match = exp.count === data.length && exp.units === units && exp.weighted === weighted;
  if (!match) ok = false;
  checks.push(`${r}: bytes=${bytes} count=${data.length} units=${units} weighted=${weighted} idsContiguous1..N=${contiguous} badFields=${badFields.length} inspectorMatch=${match} (inspector ${exp.count}/${exp.units}/${exp.weighted})`);
}
fs.writeFileSync('answer.json', JSON.stringify(out, null, 2) + '\n');
console.log('CHECKS:'); checks.forEach(c => console.log('  ' + c));
console.log('ALL_INSPECTORS_MATCH=' + ok);
console.log('WRITTEN answer.json:'); console.log(JSON.stringify(out));
